// lib/providers/agent_state_provider.dart
//
// AgentStateNotifier – central state machine for the Jack AI agent.
// States: idle → listening → processing → complete → idle
// ─────────────────────────────────────────────────────────────────────────────
import 'dart:convert';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../services/websocket_service.dart';
import '../services/action_handler.dart';

// ── Data models ───────────────────────────────────────────────────────────────

enum AgentStatus { idle, listening, processing, complete, error }

class BusResult {
  const BusResult({
    required this.operator_,
    required this.departure,
    required this.price,
  });
  final String operator_;
  final String departure;
  final String price;
}

class AgentState {
  const AgentState({
    this.status = AgentStatus.idle,
    this.transcript = '',
    this.action = '',
    this.busResults = const [],
    this.errorMessage = '',
  });

  final AgentStatus status;
  final String transcript;
  final String action;
  final List<BusResult> busResults;
  final String errorMessage;

  bool get isListening => status == AgentStatus.listening;
  bool get isProcessing => status == AgentStatus.processing;
  bool get isComplete => status == AgentStatus.complete;

  AgentState copyWith({
    AgentStatus? status,
    String? transcript,
    String? action,
    List<BusResult>? busResults,
    String? errorMessage,
  }) {
    return AgentState(
      status: status ?? this.status,
      transcript: transcript ?? this.transcript,
      action: action ?? this.action,
      busResults: busResults ?? this.busResults,
      errorMessage: errorMessage ?? this.errorMessage,
    );
  }
}

// ── State Notifier ────────────────────────────────────────────────────────────

class AgentStateNotifier extends StateNotifier<AgentState> {
  AgentStateNotifier(this._ws, this._actionHandler)
      : super(const AgentState()) {
    _listenToWebSocket();
  }

  final WebSocketService _ws;
  final ActionHandler _actionHandler;

  void _listenToWebSocket() {
    _ws.messageStream.listen(
      (raw) => _handleServerMessage(raw),
      onError: (e) {
        state = state.copyWith(
          status: AgentStatus.error,
          errorMessage: e.toString(),
        );
      },
    );
  }

  void _handleServerMessage(String raw) {
    try {
      final json = jsonDecode(raw) as Map<String, dynamic>;
      final status = json['status'] as String? ?? '';

      switch (status) {
        case 'transcript':
          state = state.copyWith(
            transcript: json['text'] as String? ?? '',
          );

        case 'processing':
          state = state.copyWith(status: AgentStatus.processing);

        case 'complete':
          final action = json['action'] as String? ?? '';
          final data = json['data'] as Map<String, dynamic>? ?? {};

          // Parse bus results if action is bus_search
          List<BusResult> buses = [];
          if (action == 'bus_search') {
            final raw = data['results'] as List<dynamic>? ?? [];
            buses = raw
                .cast<Map<String, dynamic>>()
                .map(
                  (b) => BusResult(
                    operator_: b['operator'] as String? ?? '',
                    departure: b['departure'] as String? ?? '',
                    price: b['price'] as String? ?? '',
                  ),
                )
                .toList();
          }

          state = state.copyWith(
            status: AgentStatus.complete,
            action: action,
            busResults: buses,
          );

          // Hand off to ActionHandler for any external side-effects
          _actionHandler.handle(action, data);

        case 'error':
          state = state.copyWith(
            status: AgentStatus.error,
            errorMessage: json['message'] as String? ?? 'Unknown error',
          );
      }
    } catch (_) {
      // non-JSON frame (e.g. ack) – ignore
    }
  }

  /// Called when the user taps the mic button on the Dashboard.
  Future<void> startListening() async {
    await _ws.connect();
    await _ws.startAudioStream();
    state = state.copyWith(
      status: AgentStatus.listening,
      transcript: '',
      busResults: [],
    );
  }

  /// Called when the user taps the mic again on the ActiveListening screen.
  Future<void> stopListening() async {
    await _ws.stopAudioStream();
    state = state.copyWith(status: AgentStatus.processing);
  }

  /// Hard reset back to idle (back button / cancel).
  Future<void> reset() async {
    await _ws.stopAudioStream();
    await _ws.disconnect();
    state = const AgentState();
  }
}

// ── Providers ─────────────────────────────────────────────────────────────────

final webSocketServiceProvider = Provider<WebSocketService>(
  (ref) => WebSocketService(),
);

final actionHandlerProvider = Provider<ActionHandler>(
  (ref) => ActionHandler(),
);

final agentStateProvider =
    StateNotifierProvider<AgentStateNotifier, AgentState>(
  (ref) => AgentStateNotifier(
    ref.watch(webSocketServiceProvider),
    ref.watch(actionHandlerProvider),
  ),
);
